/** Rows for `#customerTableBody`. */
export function CustomerTableBody({ onOpen, onAction }: Props) {
	const act = onAction ?? (() => undefined);
	void act;
	return (
		<>
			{initialMockData.customers.map((c, i) => (
				<RowCustomerTableBody key={i} c={c} onOpen={onOpen} onAction={act} />
			))}
		</>
	);
}

function RowCustomerTableBody({
	c,
	onOpen,
	onAction,
}: Props & { c: (typeof initialMockData.customers)[number] }) {
	const act = onAction ?? (() => undefined);
	void act;
	return (
		<>
			<tr>
				<td data-label="Customer Name">
					<strong>{c.name}</strong>
				</td>
				<td data-label="Contact">{c.phone}</td>
				<td data-label="Segment">
					<span
						className={cx(
							s.badge,
							c.seg === "VIP"
								? s.badgeP
								: c.seg === "Churn Risk"
									? s.badgeD
									: c.seg === "New"
										? s.badgeI
										: s.badgeS,
						)}
					>
						{c.seg}
					</span>
				</td>
				<td data-label="LTV (Total Spend)">{c.ltv}</td>
				<td data-label="Last Payment">{c.last}</td>
				<td data-label="Action">
					<button
						type="button"
						className={cx(s.btnPm, s.btnSm)}
						onClick={() => onOpen("sendReminderModal")}
					>
						Msg
					</button>
				</td>
			</tr>
		</>
	);
}

